-- Capture the slug on post/page work rows so a hard delete can still
-- invalidate (and remove) its slug-keyed editorial document after the
-- content row is gone. Insert/update record the current slug; delete
-- records the slug that was just removed.
ALTER TABLE `catalog_work` ADD COLUMN `entity_slug` text;--> statement-breakpoint
DROP TRIGGER IF EXISTS catalog_work_posts_insert;--> statement-breakpoint
CREATE TRIGGER catalog_work_posts_insert AFTER INSERT ON posts BEGIN INSERT INTO catalog_work (id, entity_type, entity_id, entity_slug, target_revision, processed_revision, created_at, updated_at) VALUES ('post:' || NEW.id, 'post', NEW.id, NEW.slug, 1, 0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(entity_type, entity_id) DO UPDATE SET target_revision = target_revision + 1, entity_slug = excluded.entity_slug, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;--> statement-breakpoint
DROP TRIGGER IF EXISTS catalog_work_posts_update;--> statement-breakpoint
CREATE TRIGGER catalog_work_posts_update AFTER UPDATE ON posts BEGIN INSERT INTO catalog_work (id, entity_type, entity_id, entity_slug, target_revision, processed_revision, created_at, updated_at) VALUES ('post:' || NEW.id, 'post', NEW.id, NEW.slug, 1, 0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(entity_type, entity_id) DO UPDATE SET target_revision = target_revision + 1, entity_slug = excluded.entity_slug, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;--> statement-breakpoint
DROP TRIGGER IF EXISTS catalog_work_posts_delete;--> statement-breakpoint
CREATE TRIGGER catalog_work_posts_delete AFTER DELETE ON posts BEGIN INSERT INTO catalog_work (id, entity_type, entity_id, entity_slug, target_revision, processed_revision, created_at, updated_at) VALUES ('post:' || OLD.id, 'post', OLD.id, OLD.slug, 1, 0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(entity_type, entity_id) DO UPDATE SET target_revision = target_revision + 1, entity_slug = excluded.entity_slug, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;--> statement-breakpoint
DROP TRIGGER IF EXISTS catalog_work_pages_insert;--> statement-breakpoint
CREATE TRIGGER catalog_work_pages_insert AFTER INSERT ON pages BEGIN INSERT INTO catalog_work (id, entity_type, entity_id, entity_slug, target_revision, processed_revision, created_at, updated_at) VALUES ('page:' || NEW.id, 'page', NEW.id, NEW.slug, 1, 0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(entity_type, entity_id) DO UPDATE SET target_revision = target_revision + 1, entity_slug = excluded.entity_slug, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;--> statement-breakpoint
DROP TRIGGER IF EXISTS catalog_work_pages_update;--> statement-breakpoint
CREATE TRIGGER catalog_work_pages_update AFTER UPDATE ON pages BEGIN INSERT INTO catalog_work (id, entity_type, entity_id, entity_slug, target_revision, processed_revision, created_at, updated_at) VALUES ('page:' || NEW.id, 'page', NEW.id, NEW.slug, 1, 0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(entity_type, entity_id) DO UPDATE SET target_revision = target_revision + 1, entity_slug = excluded.entity_slug, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;--> statement-breakpoint
DROP TRIGGER IF EXISTS catalog_work_pages_delete;--> statement-breakpoint
CREATE TRIGGER catalog_work_pages_delete AFTER DELETE ON pages BEGIN INSERT INTO catalog_work (id, entity_type, entity_id, entity_slug, target_revision, processed_revision, created_at, updated_at) VALUES ('page:' || OLD.id, 'page', OLD.id, OLD.slug, 1, 0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(entity_type, entity_id) DO UPDATE SET target_revision = target_revision + 1, entity_slug = excluded.entity_slug, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
